# Deepwick colors for fzf (bash and zsh). Source this from your shell rc file.
export FZF_DEFAULT_OPTS="$FZF_DEFAULT_OPTS --color=fg:#D4D4D4,bg:#04041a,hl:#569CD6 --color=fg+:#D4D4D4,bg+:#264F78,hl+:#9CDCFE --color=info:#6E7899,prompt:#569CD6,pointer:#C586C0,marker:#57A64A --color=spinner:#4EC9B0,header:#7A86A8,border:#1B2140,gutter:#04041a --color=query:#D4D4D4,label:#569CD6"
